#!/usr/bin/env bash
# =====================================================================
# CSE476, GitHub Models retirement migration.
# Repoints the course off the retired GitHub Models lane and onto Groq
# (new free default) and Ollama, and fixes three modules + five notebooks
# that hardcoded the dead github endpoint.
#
# HOW TO RUN (from the ROOT of your cse476-agentic-ai repo):
#     bash migrate_github_to_groq.sh
#
# It only overwrites the 21 files it manages. It refuses to run if you are
# not in the repo root. Nothing is committed; you review with `git diff`
# and commit yourself.
# =====================================================================
set -euo pipefail

# --- safety: must be run from the repo root ---
if [ ! -f "src/cse476/lanes.py" ] || [ ! -f "pyproject.toml" ]; then
  echo "ERROR: run this from the root of the cse476-agentic-ai repo."
  echo "       (the folder that contains src/cse476/lanes.py and pyproject.toml)"
  exit 1
fi

echo "Applying GitHub Models -> Groq migration to 21 files..."

write_file () {
  # $1 = path, stdin = base64 content
  local path="$1"
  mkdir -p "$(dirname "$path")"
  base64 -d > "$path"
  echo "  wrote $path"
}

